int main() {
  float a, b, c, alpha, beta;
  printf("Entrez a : ");
  scanf("%f", &a);
  printf("Entrez b : ");
  scanf("%f", &b);
  printf("Entrez c : ");
  scanf("%f", &c);
  if (a == 0) {
    printf("Erreur : a doit être différent de 0\n");
  } else {
    alpha = -b / (2 * a);
    beta = a * alpha * alpha + b * alpha + c;
    printf("Alpha = %f\n", alpha);
    printf("Beta = %f\n", beta);
  }
  return 0;
}

